/* ═══ Weapon art (1.7) ═════════════════════════════════════════════════════
   The first-person weapons are painted pixel art: a 3×3 sheet of 240×180
   frames, embedded below and decoded once at load. Bright pixels on the
   blades, the Ring and the holy water are marked emissive (alpha 254) so
   they glow in the dark. If the image can't be decoded (no canvas), the
   procedural drawings in 57s_arsenal.js are used instead. */
const VM_META={"revolver": {"i": 0, "muzzle": [31.7, 10.5]}, "shotgun": {"i": 1, "muzzle": [52.7, 11.9]}, "flare": {"i": 2, "muzzle": [35.7, 10.5]}, "crowbar": {"i": 3, "muzzle": null}, "holywater": {"i": 4, "muzzle": null}, "knife": {"i": 5, "muzzle": null}, "angelblade": {"i": 6, "muzzle": null}, "archangel": {"i": 7, "muzzle": null}, "ring": {"i": 8, "muzzle": null}};
const VM_IMG={ready:false,frames:{}};
const VM_ATLAS='data:image/png;base64,';
(function loadVmAtlas(){ try{ if(typeof Image==='undefined'||!document.createElement) return; const im=new Image();
  im.onload=()=>{ try{ const c=document.createElement('canvas'); c.width=im.width; c.height=im.height; const x=c.getContext('2d'); if(!x||!x.getImageData) return;
      x.drawImage(im,0,0); const D=x.getImageData(0,0,c.width,c.height).data, FW=240, FH=180;
      for(const [k,m] of Object.entries(VM_META)){ const ox=(m.i%3)*FW, oy=((m.i/3)|0)*FH, px=new Uint32Array(FW*FH);
        for(let y=0;y<FH;y++) for(let xx=0;xx<FW;xx++){ const j=((oy+y)*c.width+ox+xx)*4, a=D[j+3]; if(a<128) continue;
          px[y*FW+xx]=(((a===254?254:255)<<24)|(D[j+2]<<16)|(D[j+1]<<8)|D[j])>>>0; }
        VM_IMG.frames[k]={w:FW,h:FH,px,scale:.5,muzzle:m.muzzle}; }
      VM_IMG.ready=true; if(S.running&&typeof rebuildVM==='function') rebuildVM(); }catch(e){ console.warn('weapon art',e); } };
  im.src=VM_ATLAS; }catch(e){} })();
